INSERT OR REPLACE INTO settings (key,value,label) VALUES ('site','{"name": "迭代盛典", "en_name": "ITERATION GRAND CEREMONY", "full_name": "迭代盛典-影视专业毕业生作品颁奖盛典", "slogan": "迭代盛典，梦想的起点", "logo": "/static/img/brand/logo-full.png", "star": "/static/img/brand/star.png", "company": "迭代影视文化传媒（上海）有限公司", "address": "上海市长宁区", "phone": "", "email": "", "wechat_name": "迭代盛典", "wechat_qr": "", "icp": "", "copyright": "© 2021-2026 迭代影视文化传媒（上海）有限公司 版权所有 · “迭代盛典”为注册商标", "seo_keywords": "迭代盛典,影视专业毕业生,毕业作品,颁奖盛典,学院派,短片,电影孵化", "seo_description": "“迭代盛典-影视专业毕业生作品颁奖盛典”是针对所有高校影视专业毕业生，以纯粹影视艺术为主导方向的学院派盛典。"}','站点基础信息');
INSERT OR REPLACE INTO settings (key,value,label) VALUES ('hero','{"year": "2026", "edition_label": "第四届", "title": "迭代盛典", "subtitle": "影视专业毕业生作品颁奖盛典", "tagline": "迭代盛典，梦想的起点", "intro": "以纯粹影视艺术为主导方向的学院派盛典 —— 让每一部毕业作品被看见，让每一位青年影人被成就。", "background": "/static/img/brand/bg-space.jpg", "primary_text": "立即报名", "primary_link": "/register", "secondary_text": "提交参赛作品", "secondary_link": "/submit", "notice": "第四届“迭代盛典”影视专业毕业生作品征集现已启动"}','首页主视觉');
INSERT OR REPLACE INTO settings (key,value,label) VALUES ('about','{"title": "关于迭代盛典", "lead": "“迭代盛典-影视专业毕业生作品颁奖盛典”是针对所有高校的影视专业毕业生，以纯粹影视艺术为主导方向的学院派盛典。", "paragraphs": ["中国影视高等教育现状数据最新资料表明，目前国内的3000多所高等院校中，大约有700所开设了影视科系或专业。“迭代盛典”将全国数百家高等院校的影视专业毕业生与各种资源出口打通，掀起年度焦点，打造国内最权威的影视专业毕业生展演平台，搭建影视专业毕业生从校园走向社会的宽阔桥梁。", "“迭代盛典”是一个承载着影视专业毕业生梦想的平台，它所兼具的社会效益与商业价值得到业内专家和政府领导的一致认可。影视专业毕业生作品（联合作业）是各影视类高校的教学成果，“迭代盛典”就是将这些教学成果转化成市场价值的平台——针对优秀的毕业生作品及主创团队进行孵化，合作其所属院校，共同扶持于创作。", "未来，“迭代盛典”将凭借政策支持与商业运行相结合的操作思路运行，政府与企业形成优势互补、资源共享、彼此共赢。通过“迭代盛典”构建完整的影视产业生态体系，助力及筑就影视专业毕业生梦想中的未来——他们的未来，就是中国电影的未来！"], "company_title": "主体运营", "company_text": "2021年2月18日，“迭代影视文化传媒（上海）有限公司”在上海市长宁区注册成立，作为“迭代盛典”的主体运营公司，也是“迭代盛典”品牌唯一的合法持有方，包括但不限于名称、标识、内容、版权等。项目得到上海市长宁区政府的充分认可及支持，并与区属国企“上海东虹桥文化发展有限公司”合作承办。2022年1月7日，“迭代盛典”取得国家知识产权局颁发的商标注册证。", "image": "/static/img/pdf/graduate.jpg", "positioning": [{"title": "独树一帜", "text": "专属影视专业毕业生作品的颁奖盛典"}, {"title": "清晰的定位", "text": "纯粹影视艺术为主导方向的学院派"}, {"title": "完善的评审体系", "text": "院校初选 + 组委会复选 + 专家评审团终评"}]}','关于盛典');
INSERT OR REPLACE INTO settings (key,value,label) VALUES ('stats','[{"num": "100", "unit": "所", "label": "参与高校"}, {"num": "100,000", "unit": "人", "label": "参与人数"}, {"num": "10,000,000", "unit": "人", "label": "覆盖人群"}, {"num": "1,000,000,000", "unit": "次", "label": "累计曝光"}]','数据亮点');
INSERT OR REPLACE INTO settings (key,value,label) VALUES ('highlights','["一年一度影视专业毕业生作品汇总展示", "囊括数百家高校影视专业优秀毕业生", "点评本年度影视新生代盛事", "用时尚的观点盘点影视艺术", "用年轻的方式诠释电影梦想", "影视专业毕业生作品专属的颁奖盛典"]','活动亮点');
INSERT OR REPLACE INTO settings (key,value,label) VALUES ('support','[{"title": "孵化基金 · 筑梦未来", "icon": "fa-seedling", "image": "/static/img/pdf/seedling.jpg", "items": ["与“中国电影基金会”合作设立“迭代盛典”专项基金", "奖励“迭代盛典”各类奖项的获得者", "针对影视专业毕业生的其他剧本等影视项目给予孵化资金", "选择优秀影视项目进行辅导及投资", "影视专业毕业生自主创业投资等"]}, {"title": "迭代创投汇", "icon": "fa-clapperboard", "image": "/static/img/pdf/clapper.jpg", "items": ["直击影视项目融资难的痛点，主投N部影视项目", "获奖作品主创团队：3部", "提名作品主创团队：2部", "入围作品主创团队：1部", "迭代MCN矩阵平台的其他毕业生：N部", "所有主投影视项目，均有影视界资深专家导师辅佐监制"]}, {"title": "创业扶持 · 筑梦未来", "icon": "fa-rocket", "image": "/static/img/pdf/crew.jpg", "items": ["针对毕业生的需求，对接“迭代盛典”创业项目", "针对各类奖项获得者，在指定园区注册公司，提供相关扶持帮助", "加入“迭代MCN矩阵”的毕业生，原创短视频可共享平台流量及分账回报", "免费加入“迭代影视专业人才库”，优先参与“迭代创投汇”所投影片的参演或制片工作", "“迭代盛典”平台免费提供研学实习机会的对接"]}]','扶持计划');
INSERT OR REPLACE INTO settings (key,value,label) VALUES ('ecosystem','{"title": "影视产业生态体系", "text": "透过“迭代盛典”与各高校资源形成平台，延伸出研学教育、影视制作、网络科技、版权运营、演艺经纪、广告传媒、产业园区及影视金融科技平台的影视产业生态体系。“迭代影视金融科技平台”以专业化管理和科技手段支撑，与银行、保险公司形成合作关系，既解决影视项目融资难的问题，又有效规避影视投资回收的风险，带动影视专业毕业生的创新创业和园区入驻企业的持续发展。", "items": [{"name": "研学教育", "icon": "fa-graduation-cap"}, {"name": "影视制作", "icon": "fa-film"}, {"name": "网络科技", "icon": "fa-microchip"}, {"name": "版权运营", "icon": "fa-copyright"}, {"name": "演艺经纪", "icon": "fa-user-tie"}, {"name": "广告传媒", "icon": "fa-bullhorn"}, {"name": "产业园区", "icon": "fa-building"}, {"name": "影视金融科技平台", "icon": "fa-coins"}]}','产业生态');
INSERT OR REPLACE INTO settings (key,value,label) VALUES ('rules','{"title": "迭代盛典-影视专业毕业生作品颁奖盛典 作品征集", "deadline": "9月30日", "sections": [{"title": "参赛作品的要求", "items": ["由应届毕业生拍摄的影像作品，内容、主题自行拟定", "作品类型：剧情片、纪录片、动画片", "上述作品可以以任何活动影像记录介质拍摄", "作品时长：短片45分钟以内，长片90分钟以内，原则上拒绝超出规定时长的作品", "作品必须为参赛者原创，如有版权争议、纠纷自行承担法律责任"]}, {"title": "参赛作品的提交", "items": ["参赛作品提交日为9月30日以前，自备硬盘/U盘，以数据的形式拷贝，或传输至百度网盘", "提交内容：制作完成的短、长片作品、文字说明、相关照片等作品资料，放置于同一文件夹中，文件夹命名格式为“年级专业、类型（短、长片）、作品名称”", "所提交的影像文件名为片名，作品格式为高清MP4播放格式", "作品须附上相关文字说明（电子版）：纪录片须包含分组成员名单、作品内容简介等；剧情片须包含作品简介、剧本或剧本梗概、演职员表（包含编剧、导演、摄像、剪辑、演员等）", "相关照片为工作照、剧照、自制海报等，清晰命名"]}, {"title": "参赛作品的遴选", "items": ["每所院校可选10部作品参赛，类别不限，包括剧情片、纪录片、动画片", "提交的作品将由学校组织专业老师进行评审后再选送交“迭代盛典”组委会", "组委会组织专业评审团队进行复选工作，评选出“迭代盛典”入围作品", "由“迭代盛典”专家评审团对入围作品进行提名甄选"]}]}','作品征集规则');
INSERT OR REPLACE INTO settings (key,value,label) VALUES ('awards','[{"cn": "最佳影片", "en": "Best Picture"}, {"cn": "最佳导演", "en": "Best Directing"}, {"cn": "最佳男主角", "en": "Best Actor in a Leading Role"}, {"cn": "最佳女主角", "en": "Best Actress in a Leading Role"}, {"cn": "最佳男配角", "en": "Best Actor in a Supporting Role"}, {"cn": "最佳女配角", "en": "Best Actress in a Supporting Role"}, {"cn": "最佳原创剧本", "en": "Best Writing (Original Screenplay)"}, {"cn": "最佳改编剧本", "en": "Best Writing (Adapted Screenplay)"}, {"cn": "最佳摄影", "en": "Best Cinematography"}, {"cn": "最佳剪辑", "en": "Best Film Editing"}, {"cn": "最佳音效剪辑", "en": "Best Sound Editing"}, {"cn": "最佳音响效果", "en": "Best Sound Mixing"}, {"cn": "最佳视觉效果", "en": "Best Visual Effects"}, {"cn": "最佳化妆与发型设计", "en": "Best Makeup and Hairstyling"}, {"cn": "最佳服装设计", "en": "Best Costume Design"}, {"cn": "最佳艺术指导", "en": "Best Production Design"}, {"cn": "最佳原创配乐", "en": "Best Music (Original Score)"}, {"cn": "最佳原创歌曲", "en": "Best Music (Original Song)"}, {"cn": "最佳原创音乐剧", "en": "Best Music (Original Musical)"}, {"cn": "最佳动画长片", "en": "Best Animated Feature Film"}, {"cn": "最佳动画短片", "en": "Best Short Film (Animated)"}, {"cn": "最佳真人短片", "en": "Best Short Film (Live Action)"}, {"cn": "最佳纪录长片", "en": "Best Documentary (Feature)"}, {"cn": "最佳纪录短片", "en": "Best Documentary (Short Subject)"}]','奖项设置');
INSERT OR REPLACE INTO settings (key,value,label) VALUES ('timeline','[{"date": "2021.02.18", "title": "主体公司成立", "text": "迭代影视文化传媒（上海）有限公司在上海市长宁区注册成立，作为“迭代盛典”主体运营公司及品牌唯一合法持有方。"}, {"date": "2021.03.19", "title": "启动发布会", "text": "“迭代论坛—中国电影的未来”暨“迭代盛典-筑梦未来—启动发布会”在上海虹桥艺术中心开幕举办。"}, {"date": "2021.07.28", "title": "长宁区重点项目", "text": "作为上海市长宁区重点项目，参加长宁区投资促进签约大会并在重点项目签约仪式上签约。"}, {"date": "2022.01.07", "title": "商标注册", "text": "“迭代盛典”取得国家知识产权局颁发的商标注册证。"}, {"date": "2022.02", "title": "首届盛典圆满举行", "text": "2021年度“迭代盛典”共颁发11个奖项，16部作品获得单项奖。"}, {"date": "2023", "title": "牵手上戏", "text": "迭代与上海戏剧学院电影学院签署合作备忘录。"}, {"date": "2024", "title": "2024-迭代盛典", "text": "与上海戏剧学院共同联合主/承办“2024-迭代盛典”。"}, {"date": "2025.12.21", "title": "2025迭代盛典 · 北京", "text": "颁奖典礼在北京举办，揭晓11项大奖，同步举行“迭代巴中战略合作协议”签约仪式。"}, {"date": "2026.06.22", "title": "第四届作品征集启动", "text": "亚视云·迭代影视OPC社区发布会暨第四届“迭代盛典”作品征集启动大会在上海举行，八大城市授牌。"}]','发展历程');
INSERT OR REPLACE INTO settings (key,value,label) VALUES ('organizers','[{"role": "主办方", "names": "迭代盛典组委会"}, {"role": "承办方", "names": "迭代影视文化传媒（上海）有限公司、上海东虹桥文化发展有限公司"}, {"role": "联合承办", "names": "巴中市新闻传媒集团有限公司、山西华标文化产业集团有限公司"}, {"role": "协办方", "names": "共生联盟投资发展有限公司、联合万邦（北京）国际文化传媒有限公司、北京新纪元电影发展公司、北京竹韵文化传媒有限公司、北京豪艺博雅企业经营策划有限公司、上海月下萌胧文化传媒有限公司、青年影联（武汉）文化发展有限公司、山西晋泰集团有限公司、山西云韵腾像影视文化传播有限公司"}, {"role": "支持方", "names": "中国电影基金会、中国电影博物馆、中央广播电视总台-国际在线、海尔智家 Leader"}]','组织架构');
INSERT OR REPLACE INTO settings (key,value,label) VALUES ('promotion','{"title": "全媒体传播", "text": "“迭代盛典”全面整合电视、报刊、杂志等传统媒体资源与互联网新媒体资源，形成“全媒体概念”新型共享传播体系，实现线上线下地毯式传播推广，精准覆盖受众人群。", "channels": ["线上展映 · 中央广播电视总台-国际在线", "线下展映 · 中国电影博物馆", "网络评选 · 官方APP投票", "微博抖音超话榜 · 年度爆款话题", "迭代之夜 & 慈善晚宴"], "media": ["新华网", "国际在线", "人民网", "新浪网", "微博", "抖音", "快手", "爱奇艺", "腾讯视频", "优酷", "芒果TV", "哔哩哔哩", "今日头条", "知乎", "搜狐", "网易", "凤凰网", "百度", "豆瓣", "CCTV6 电影频道"]}','传播矩阵');
INSERT OR REPLACE INTO settings (key,value,label) VALUES ('cta','{"title": "他们的未来，就是中国电影的未来", "text": "未来，将从这里涌现出无数的大明星、大导演、大编剧、大摄影、大制片人等影视行业的精英人士！期待现在和将来有更多的机构与企业支持这个以纯粹影视艺术为主导方向的学院派盛典。", "button_text": "商务合作咨询", "button_link": "/contact"}','页尾号召');
