INSERT INTO editions (year,title,theme,event_date,venue,summary,content,cover,status,registration_open,submission_open,sort,submission_deadline) VALUES (2021,'首届迭代盛典','筑梦未来','2021-03-19 启动 / 2022-02 颁奖','上海虹桥艺术中心','首届“迭代盛典-影视专业毕业生作品颁奖盛典”（筑梦未来）。共颁发11个奖项，16部作品获得单项奖。','<p>2021年3月19日，“迭代论坛—中国电影的未来”暨“迭代盛典-筑梦未来—启动发布会”在上海虹桥艺术中心开幕举办。</p><p>“筑梦未来-颁奖盛典”系统性地整合全国数百家高校影视专业毕业生资源，针对各院校选送的学生影视短、长片作品，由影视业界资深专家评审团队进行评选，对优秀作品进行颁奖。</p><p>首届盛典共颁发11个奖项，16部作品获得单项奖。上海戏剧学院电影学院《乔迁之喜》获最佳编剧奖，《三只小蝴蝶》获最佳剪辑奖；北京电影学院《我，杨栋梁决定去做一件错事》获最佳男主角奖；《收获月影的季节》获最佳美术奖与最佳摄影奖。</p>','/static/img/news/wx-2022-02-winners.jpg','finished',0,0,1,NULL);
INSERT INTO editions (year,title,theme,event_date,venue,summary,content,cover,status,registration_open,submission_open,sort,submission_deadline) VALUES (2024,'2024-迭代盛典','梦想的起点','2024','上海','迭代盛典与上海戏剧学院共同联合主/承办“2024-迭代盛典”。','<p>2023年，迭代与上海戏剧学院电影学院签署合作备忘录；2024年双方共同联合主/承办“2024-迭代盛典”。</p><p>为发现更多影视人才、更好地培养与扶持人才，迭代正与上海戏剧学院继续教育学院磋商开办高起本表演专业（上戏迭代班），为“迭代盛典”后续不断孵化投拍的电影项目储备表演人才。</p>','/static/img/pdf/2024-group.jpg','finished',0,0,2,NULL);
INSERT INTO editions (year,title,theme,event_date,venue,summary,content,cover,status,registration_open,submission_open,sort,submission_deadline) VALUES (2025,'2025迭代盛典','影视专业毕业生作品颁奖典礼','2025-12-21','北京','颁奖典礼在北京举办，揭晓最佳影片、最佳导演、最佳编剧、最佳男演员、最佳女演员等11项奖项，同步举行“迭代巴中战略合作协议”签约仪式。','<p>2025年12月21日，“2025迭代盛典——影视专业毕业生作品颁奖典礼”在北京举办，现场揭晓了最佳编剧、最佳男演员、最佳女演员、最佳导演、最佳影片等11项奖项，并为获奖作品及主创团队颁发荣誉证书及奖杯。</p><p>颁奖典礼上同步举行“迭代巴中战略合作协议”签约仪式，旨在为优秀影视毕业生作品提供院线电影孵化帮助，推动从创作到上映的全流程支持。</p><p>本届盛典还邀请影视院校毕业生、行业专家及演员共同参观中国电影博物馆《为人民抒怀 为时代放歌——新时代中国电影发展成就展暨中国电影诞生120周年数字影像展》。</p>','/static/img/pdf/sign-bazhong.jpg','finished',0,0,3,NULL);
INSERT INTO editions (year,title,theme,event_date,venue,summary,content,cover,status,registration_open,submission_open,sort,submission_deadline) VALUES (2026,'第四届迭代盛典','AI+影视 · 梦想的起点','2026','上海','第四届“迭代盛典”影视专业毕业生作品征集已于2026年6月22日正式启动，面向全国高校影视专业应届毕业生征集剧情片、纪录片、动画片。','<p>2026年6月22日，亚视云·迭代影视OPC社区发布会、第四届“迭代盛典”影视专业毕业生作品征集启动大会暨八大城市授牌仪式在上海举行。</p><p>第四届“迭代盛典”影视专业毕业生作品征集正式启动，北京、上海、成都、西安、厦门、郑州、南平及马来西亚八座城市获授“OPC影视社区共建基地”称号。</p><p>欢迎全国影视院校应届毕业生踊跃报名、提交作品。</p>','/static/img/pdf/launch-stage.jpg','open',1,1,4,'2026-09-30');
