INSERT INTO people (name,category,title,bio,photo,sort,visible) VALUES ('靳玉强','founder','“迭代盛典”创始人','“迭代盛典”创始人，迭代影视文化传媒（上海）有限公司创办人。以毕业生作品为起点，推动构建“产业园区+影视金融科技平台”的影视产业生态体系。','',0,1);
INSERT INTO people (name,category,title,bio,photo,sort,visible) VALUES ('杨步亭','founder','“迭代盛典”发起人 · 中国电影发行放映协会会长','曾任中国电影科研所所长、中国电影发行放映协会会长、国家广电总局电影事业管理局副局长、中国电影集团公司董事长；现任中国电影海外推广有限责任公司董事长。','/static/img/people/yangbuting.jpg',1,1);
INSERT INTO people (name,category,title,bio,photo,sort,visible) VALUES ('张会军','founder','“迭代盛典”发起人 · 北京电影学院原院长','曾任北京电影学院院长、第十届全国政协委员、全国政协教科文卫体委员会委员、国家教育部高等学校素质教育工作委员会委员、北京影视艺术家协会副主席等社会职务。','/static/img/people/zhanghuijun.jpg',2,1);
INSERT INTO people (name,category,title,bio,photo,sort,visible) VALUES ('岳晓湄','founder','“迭代盛典”发起人 · 资深制片人','中国电影艺术研究中心研究馆员，中国电影家协会会员，首都影金会特邀研究员。曾任云南电影集团副总裁兼影业公司总经理、星美传媒集团副总裁兼星美影业有限公司总经理。','/static/img/people/yuexiaomei.jpg',3,1);
INSERT INTO people (name,category,title,bio,photo,sort,visible) VALUES ('陈东','judge','专家评审','曾任上海市委宣传部副部长、上海市人大内务司法委员会副主任委员、上海市第十五届人民代表大会代表、上海世博会上海馆馆长、上海市文化发展基金会理事长等职务。','/static/img/people/chendong.jpg',4,1);
INSERT INTO people (name,category,title,bio,photo,sort,visible) VALUES ('姚云','judge','专家评审 · 国家一级作家','国家一级作家、编剧、浙江省作家协会副主席。电影作品：《边城》《谁是第三者》《小刺猬奏鸣曲》《四个小伙伴》《为什么生我》《泪洒台北》《潜网》等。','/static/img/people/yaoyun.jpg',5,1);
INSERT INTO people (name,category,title,bio,photo,sort,visible) VALUES ('刘沛','judge','专家评审 · 资深监制','40多年影视制作经历，600多部集影视作品监制、制片人等。曾任职北京科教电影厂、北京卫生教育所影视中心、中国化工进出口总公司影视部、世纪英雄电影投资公司副总经理。','/static/img/people/liupei.jpg',6,1);
INSERT INTO people (name,category,title,bio,photo,sort,visible) VALUES ('邵永平','judge','专家评审 · 艺术家、策展人','旅美海归艺术家、策展人，上海戏剧家协会会员、中国曲艺家协会会员、上海曲艺家协会理事。代表作品：《阿潭内传》《贺龙在武当山》《爱情日记》等。','/static/img/people/shaoyongping.jpg',7,1);
INSERT INTO people (name,category,title,bio,photo,sort,visible) VALUES ('高伟宁','judge','专家评审 · 导演','中国电视剧导演工作委员会会员、最高人民检察院影视中心导演、小鸟观映点播院线创始人。代表作品：《母亲是条河》《红树林》《正义的重量》《苗山花》等。','/static/img/people/gaoweining.jpg',8,1);
INSERT INTO people (name,category,title,bio,photo,sort,visible) VALUES ('杨志顺','judge','专家评审 · 电影制片人','电影制片人，加拿大国际华语电影协会名誉理事、北京电影协会VR电影专业委员会副秘书长、山西工商学院特聘教授、北京文化发展研究院合作人、盛尚传媒执行董事。','/static/img/people/yangzhishun.jpg',9,1);
INSERT INTO people (name,category,title,bio,photo,sort,visible) VALUES ('杨步亭','judge','专家评审','曾任中国电影科研所所长、中国电影发行放映协会会长、国家广电总局电影事业管理局副局长、中国电影集团公司董事长；现任中国电影海外推广有限责任公司董事长。','/static/img/people/yangbuting.jpg',-3,1);
INSERT INTO people (name,category,title,bio,photo,sort,visible) VALUES ('张会军','judge','专家评审','曾任北京电影学院院长、第十届全国政协委员、全国政协教科文卫体委员会委员、国家教育部高等学校素质教育工作委员会委员、北京影视艺术家协会副主席等社会职务。','/static/img/people/zhanghuijun.jpg',-2,1);
INSERT INTO people (name,category,title,bio,photo,sort,visible) VALUES ('岳晓湄','judge','专家评审','中国电影艺术研究中心研究馆员，中国电影家协会会员，首都影金会特邀研究员。曾任云南电影集团副总裁兼影业公司总经理、星美传媒集团副总裁兼星美影业有限公司总经理。','/static/img/people/yuexiaomei.jpg',-1,1);
