INSERT INTO news (title,category,source,published_at,featured,cover,summary,content,source_url,status,author) VALUES ('第四届“迭代盛典”影视专业毕业生作品征集正式启动','notice','迭代盛典组委会','2026-06-22',1,'/static/img/pdf/launch-stage.jpg','第四届“迭代盛典”面向全国高校影视专业应届毕业生征集剧情片、纪录片、动画片，提交截止日期为9月30日。','<p>第四届“迭代盛典”影视专业毕业生作品征集正式启动！</p><p>“迭代盛典-影视专业毕业生作品颁奖盛典”是针对所有高校的影视专业毕业生，以纯粹影视艺术为主导方向的学院派盛典。</p><p><strong>【参赛作品要求】</strong>由应届毕业生拍摄的影像作品，内容、主题自行拟定；作品类型为剧情片、纪录片、动画片；短片45分钟以内，长片90分钟以内；作品必须为参赛者原创。</p><p><strong>【参赛作品提交】</strong>参赛作品提交日为9月30日以前，可通过本网站“作品提交”入口在线登记，并通过硬盘/U盘拷贝或百度网盘传输作品文件。</p><p><strong>【参赛作品遴选】</strong>每所院校可选10部作品参赛；学校组织专业老师评审后选送组委会；组委会组织专业评审团队复选出入围作品；由专家评审团对入围作品进行提名甄选。</p><p>欢迎全国影视院校应届毕业生踊跃报名！</p>',NULL,'published','迭代盛典组委会');
INSERT INTO news (title,category,source,source_url,published_at,featured,cover,summary,content,status,author) VALUES ('亚视云·迭代影视OPC社区发布会暨第四届“迭代盛典”征集启动大会在上海举行','media','南方周刊 / 搜狐','https://www.sohu.com/a/1041812163_122908012','2026-06-24',1,'/static/img/pdf/launch-group.jpg','发布会上聘请陈东、杨步亭、张会军、岳晓湄、张兆国担任顾问，宣布第四届“迭代盛典”作品征集正式启动，并为八大城市授牌。','<p>2026年6月22日，亚视云·迭代影视OPC社区发布会、第四届“迭代盛典”影视专业毕业生作品征集启动大会暨八大城市授牌仪式在上海举行。</p><p>杨步亭、黄昌勇、陈东、岳晓湄、张会军、张兆国等嘉宾出席会议。当日，亚视云迭代影视OPC社区正式聘请陈东、杨步亭、张会军、岳晓湄、张兆国等专家领导担任顾问，为社区未来发展提供支撑。</p><p>会上宣布第四届“迭代盛典”影视专业毕业生作品征集正式启动，并向北京、上海、成都、西安、厦门、郑州、南平及马来西亚八座城市授予“OPC影视社区共建基地”称号。</p><p>以“亚视云”为算力底座、以“迭代影视OPC”为内容生态，双方共同探索“AI+影视+教育+城市+社区”的产业新格局，为青年创作者提供算力、存储、工具与培训等支撑。</p>','published','南方周刊 / 搜狐');
INSERT INTO news (title,category,source,source_url,published_at,featured,cover,summary,content,status,author) VALUES ('“2025迭代盛典——影视专业毕业生作品颁奖典礼”在北京举办','media','新华网','http://www.xinhuanet.com/fortune/20251222/269b5ea4428a4dd58a6defeceb5a407c/c.html','2025-12-22',1,'/static/img/pdf/sign-bazhong.jpg','典礼揭晓最佳编剧、最佳男演员、最佳女演员、最佳导演、最佳影片等11项奖项，并同步举行“迭代巴中战略合作协议”签约仪式。','<p>12月21日，“2025迭代盛典——影视专业毕业生作品颁奖典礼”在北京举办。活动现场揭晓了最佳编剧、最佳男演员、最佳女演员、最佳导演、最佳影片等11项奖项，并为获奖作品及主创团队颁发荣誉证书及奖杯。</p><p>“迭代盛典”自2021年创立以来，通过孵化优秀作品、联动院校资源，致力于将影视院校教学成果转化为市场价值。</p><p>北京电影学院教授、“迭代盛典”发起人张会军表示，希望在学校、企业、行业等多方力量帮扶下，把获奖短片逐步孵化成院线长片。</p><p>中国电影行业资深制片人、“迭代盛典”发起人岳晓湄表示，“迭代盛典”有长期、落地的计划，最终要将孵化成熟的作品做成全产业链的协同产品，帮助学生积累经验，早日成为电影行业需要的人才。</p><p>中国电影发行放映协会会长、“迭代盛典”发起人杨步亭谈到，新技术能更好地满足人们对影视多样化的需求，但电影的魂始终是故事。</p><p>颁奖典礼上同步举行了“迭代巴中战略合作协议”签约仪式，为优秀影视毕业生作品提供院线电影孵化帮助，推动从创作到上映的全流程支持。本届盛典还组织毕业生、行业专家及演员参观了中国电影博物馆举办的新时代中国电影发展成就展。</p>','published','新华网');
INSERT INTO news (title,category,source,published_at,featured,cover,summary,content,source_url,status,author) VALUES ('“迭代盛典”与上海戏剧学院联合主/承办“2024-迭代盛典”','news','迭代盛典组委会','2024-06-01',0,'/static/img/pdf/2024-group.jpg','继2023年签署合作备忘录后，迭代与上海戏剧学院电影学院共同联合主/承办“2024-迭代盛典”。','<p>2023年，迭代与上海戏剧学院电影学院签署了合作备忘录，又于2024年共同联合主/承办了“2024-迭代盛典”。</p><p>为了发现更多的影视人才，更好地培养、扶持人才，迭代正在与上海戏剧学院继续教育学院磋商开办高起本表演专业（上戏迭代班），为“迭代盛典”后续不断孵化投拍的电影项目储备表演人才。</p><p>目前，“迭代盛典”已与上海戏剧学院、北京电影学院、青岛电影学院等十多所高校，就共同扶持毕业生获奖作品孵化长片电影项目达成合作意向。</p>',NULL,'published','迭代盛典组委会');
INSERT INTO news (title,category,source,source_url,published_at,featured,cover,summary,content,status,author) VALUES ('芒种促新机 迭代传佳音 | 上戏电影学院作品斩获首届“迭代盛典”多项大奖','media','上海戏剧学院电影学院','https://xxgk.sta.edu.cn/94/da/c3457a103642/page.htm','2022-03-28',0,'/static/img/posters/poster-14.jpg','《乔迁之喜》获最佳编剧奖，《三只小蝴蝶》获最佳剪辑奖，《完美小孩》获最佳编剧提名奖及最佳女主角提名奖。','<p>在2021年度首届“迭代盛典——影视专业毕业生作品颁奖盛典”上，上海戏剧学院电影学院多部作品获奖：</p><p>胡向真、薛驰原编剧、导演的剧情短片《乔迁之喜》获得最佳编剧奖（指导教师：肖湘宁、赵武）。</p><p>陈笑编剧、导演，黄强担任剪辑的《三只小蝴蝶》获得最佳剪辑奖（指导教师：方虹、陶军）。</p><p>周莹编剧、导演的《完美小孩》获得最佳编剧提名奖，影片主演邱佳君获得最佳女主角提名奖。</p><p>蔡昀岑编剧、导演的《好孩子》，张玉晗编剧、导演的《娜娜》，刘翌昕编剧、导演的《天之限》，董涛编剧、导演的《重逢》获得优秀入围作品奖。</p><p>“迭代盛典”通过整合全国数百家高校影视专业毕业生资源，针对影视专业毕业生作品进行征集、评选、颁奖，发掘甄选其中优秀的作品以及创意独特的主创团队，与其所属院校深度合作、共同孵化扶持其长片创作。</p>','published','上海戏剧学院电影学院');
INSERT INTO news (title,category,source,published_at,featured,cover,summary,content,source_url,status,author) VALUES ('2021迭代盛典获奖作品','wechat','迭代盛典 微信公众号','2022-02-22',1,'/static/img/news/wx-2022-02-winners.jpg','2021年度“迭代盛典-影视专业毕业生作品颁奖盛典”圆满举行完成。本次“迭代盛典”共颁发了11个奖项，有16部作品获得单项奖。','<p>日前，2021年度“迭代盛典-影视专业毕业生作品颁奖盛典”圆满举行完成。本次“迭代盛典”共颁发了11个奖项，有16部作品获得单项奖。</p><figure><img src="/static/img/pdf/award-01.jpg" alt=""></figure><p>部分获奖作品：</p><p>《乔迁之喜》（上海戏剧学院电影学院）—— 最佳编剧奖</p><p>《三只小蝴蝶》（上海戏剧学院电影学院）—— 最佳剪辑奖</p><p>《我，杨栋梁决定去做一件错事》（北京电影学院）—— 最佳男主角奖</p><p>《收获月影的季节》—— 最佳美术奖、最佳摄影奖</p><figure><img src="/static/img/pdf/award-05.jpg" alt=""></figure><p>“迭代盛典”是一个承载着影视专业毕业生梦想的平台，通过整合全国数百家高校影视专业毕业生资源，针对影视专业毕业生作品进行征集、评选、颁奖，发掘甄选其中优秀的作品以及创意独特的主创团队，与其所属院校深度合作、共同孵化扶持其长片创作，打造国内最权威的影视专业毕业生作品的展映及孵化平台。</p><figure><img src="/static/img/pdf/award-12.jpg" alt=""></figure>',NULL,'published','迭代盛典 微信公众号');
INSERT INTO news (title,category,source,published_at,featured,cover,summary,content,source_url,status,author) VALUES ('“迭代盛典”取得国家知识产权局商标注册证','news','迭代盛典组委会','2022-01-07',0,'/static/img/brand/logo-full.png','2022年1月7日，“迭代盛典”取得由国家知识产权局颁发的商标注册证。','<p>2022年1月7日，“迭代盛典”取得由国家知识产权局颁发的商标注册证。</p><p>迭代影视文化传媒（上海）有限公司作为“迭代盛典”的主体运营公司，是“迭代盛典”品牌唯一的合法持有方，包括但不限于名称、标识、内容、版权等。</p>',NULL,'published','迭代盛典组委会');
INSERT INTO news (title,category,source,published_at,featured,cover,summary,content,source_url,status,author) VALUES ('“迭代盛典”被定为上海市长宁区重点项目','news','迭代盛典组委会','2021-07-28',0,'/static/img/pdf/sign-changning-2.jpg','2021年7月28日，长宁区召开投资促进季度签约大会，“迭代盛典”项目位列27个重点签约项目之中。','<p>2021年7月28日下午，上海市长宁区召开投资促进季度签约大会。区委书记王岚，区委副书记、区长张伟，区委常委、副区长杨元飞，区人大常委会副主任夏利民，副区长翁华建，区政协副主席朱辉等出席大会。</p><figure><img src="/static/img/pdf/sign-changning-1.jpg" alt=""></figure><p>此次签约共有27个重点项目企业在现场签约落户长宁，涵盖航空服务业、互联网+生活性服务业、时尚创意产业三个长宁特色产业，以及人工智能、金融服务、大健康三个长宁潜力产业。由“迭代影视文化传媒（上海）有限公司”与长宁区属国企“上海东虹桥文化发展有限公司”签署的“迭代盛典”项目位列其中。</p><figure><img src="/static/img/pdf/sign-changning-2.jpg" alt=""></figure>',NULL,'published','迭代盛典组委会');
INSERT INTO news (title,category,source,published_at,featured,cover,summary,content,source_url,status,author) VALUES ('“筑梦未来-颁奖盛典”启动发布会圆满开幕！','wechat','迭代盛典 微信公众号','2021-03-20',1,'/static/img/news/wx-2021-03-launch.jpg','“迭代论坛-中国电影的未来”暨“筑梦未来-影视专业毕业生作品颁奖盛典”启动发布会在上海虹桥艺术中心正式开幕。','<p>“筑梦未来-影视专业毕业生作品颁奖盛典”（以下简称“筑梦未来-颁奖盛典”）系统性地整合全国数百家高校影视专业毕业生资源，将毕业生影视作品进行征集，由资深专家评审团队进行评选，对优秀作品进行颁奖。</p><figure><img src="/static/img/pdf/launch-stage.jpg" alt=""></figure><p>2021年3月19日，“迭代论坛-中国电影的未来”暨“筑梦未来-影视专业毕业生作品颁奖盛典”启动发布会在上海虹桥艺术中心正式开幕。</p><p>依托颁奖盛典平台，发现与扶持好的作品创意和团队，合作所在院校，扶持其创作，与各强势资源对接，打造国内最权威的影视专业毕业生展演平台。</p><figure><img src="/static/img/pdf/launch-group.jpg" alt=""></figure><p>未来，“筑梦未来-颁奖盛典”将凭借政策支持与商业运作相结合的模式，政府与企业形成优势互补、资源共享、彼此共赢。同时，通过颁奖盛典构建完整的影视生态体系，助力及筑就毕业生梦想中的未来。</p><figure><img src="/static/img/pdf/launch-forum.jpg" alt=""></figure><p>“筑梦未来-颁奖盛典”是一个承载着影视专业毕业生梦想的平台，每年将源源不断汇集众多影视专业毕业生作品，涌现出更多优秀的编剧、导演、演员等主创新生力量。期待更多的业界朋友来支持这个以纯粹影视艺术为主导方向的学院派盛典。</p>',NULL,'published','迭代盛典 微信公众号');
INSERT INTO news (title,category,source,published_at,featured,cover,summary,content,source_url,status,author) VALUES ('筑梦未来-颁奖盛典 | 毕业季的主旋律','wechat','迭代盛典 微信公众号','2021-02-08',0,'/static/img/news/wx-2021-02-graduation.jpg','“筑梦未来-颁奖盛典”系统性地整合各高校影视专业毕业生资源，针对各院校选送的学生影视短、长片作品，由影视业界资深专家进行评选。','<p>毕业即失业，似乎真的成为了毕业季的主旋律？！就业还是失业，由过往的自己决定。一边做自己喜欢的事情，一边创造着价值和收益。</p><figure><img src="/static/img/pdf/graduation-season.jpg" alt=""></figure><p>每到毕业季，应届大学毕业生将涌入这个巨大的社会，在择业与就业中徘徊选择。面对梦想缺乏勇气又无法舍弃，虚耗之中，内心产生无法驱散的梦魇。</p><p>中国影视高等教育现状数据资料表明，目前国内3000多所高等院校中，大约有700所开设了影视科系或专业。</p><p>“筑梦未来-颁奖盛典”系统性地整合各高校影视专业毕业生资源，针对各院校选送的学生影视短、长片作品，由影视业界资深专家、学者组成的评审团队进行评选，对优秀作品进行颁奖，将全国数百家高等院校的影视专业毕业生与各种资源出口打通，搭建影视专业毕业生从校园走向社会的宽阔桥梁。</p><figure><img src="/static/img/pdf/dream-jump.jpg" alt=""></figure><p>“迭代盛典-影视专业毕业生作品颁奖盛典”是针对所有高校的影视专业毕业生，以纯粹影视艺术为主导方向的学院派盛典！</p>',NULL,'published','迭代盛典 微信公众号');
INSERT INTO news (title,category,source,source_url,published_at,featured,cover,summary,content,status,author) VALUES ('一个专门对接影视专业毕业生的扶持体系，在上海按下了启动键','media','文汇报','https://wenhui.whb.cn/zhuzhan/xinwen/20210320/396809.html','2021-03-20',0,'/static/img/pdf/launch-forum.jpg','怎样让梦想找到合适的土壤，怎样为中国电影发现更适配的人才，是中国电影闯未来的课题之一。','<p>每年影视专业的毕业生是个庞大的群体。怀揣着影视梦想的年轻人，该如何面对走出校门后的挑战？与此同时，正在建设电影强国的中国电影，亟需一大批掌握了先进电影理念又对中国文化深刻认同的新生力量。</p><p>“迭代论坛-中国电影的未来”暨“筑梦未来-影视专业毕业生作品颁奖盛典”启动发布会在上海虹桥艺术中心正式开幕，一个专门对接影视专业毕业生即“学院派”人才的扶持体系，在上海按下了启动键。</p><p>据报道，“筑梦未来-颁奖盛典”将通过整合全国数百家高校影视专业毕业生资源，将毕业生影视作品进行征集，由资深专家评审团队进行评选，对优秀作品进行颁奖；同时依托颁奖盛典平台，发现与扶持好的作品创意和团队，合作所在院校，扶持其创作，与各强势资源对接。</p>','published','文汇报');
